var i=[{title:`Bovenlichaam`,text:`De borstspieren helpen de armen naar voren of over de romp te duwen, zoals bij push-ups en borstpersen. De brede rugspier (latissimus dorsi) en andere rugspieren helpen de armen te trekken en de schouderbladen te controleren bij roeibewegingen en pull-ups. De deltaspieren helpen de armen op te tillen en te bewegen. De biceps buigt de elleboog en helpt bij sommige trekbewegingen, en de triceps strekt de elleboog tijdens persen.`},{title:`Onderlichaam`,text:`De quadriceps strekt de knie en helpt bij squatten, stappen en lunges. De bilspieren strekken of stabiliseren de heup, en heupscharnieren en step-ups kunnen ze uitdagen. De hamstrings buigen de knie en helpen bij heupstrekking. De kuitspieren zorgen voor plantairflexie van de enkel bij wandelen, rennen en kuitheffen. De heupadductoren en -abductoren helpen de beenpositie te beheersen en het bekken stabiel te houden.`},{title:`Romp (de core)`,text:`De rechte buikspier, schuine buikspieren, diepere buikspieren, rugstrekkers en verschillende spieren rond het bekken helpen kracht door te geven en te weerstaan. Planks, carries en beheerste heupscharnieren dagen de rompstabiliteit in verschillende richtingen uit. Zichtbare „buikspieren” zijn maar één onderdeel van dit systeem.`},{title:`Overlap tussen oefeningen`,text:`Een squat werkt meer dan alleen de quadriceps, en roeien werkt meer dan alleen de lats. Grip, romphoek, bewegingsbereik en je eigen anatomie bepalen welke spieren meer van het werk doen. Organiseer de week van een beginner rond squats, heupscharnieren, lunges, duwen, trekken en corewerk, en wijs niet elke training aan één spier toe.`},{title:`TrainUp gebruiken`,text:`Elke oefeningpagina bij Oefeningen toont het bewegingspatroon en de spieren die worden getraind, wat helpt om met een klein aantal oefeningen je hele lichaam te dekken. Isolatiewerk kan een specifiek gat vullen, maar vervangt niet het leren van de basale meergewrichtsbewegingen.`}];var t=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Overzicht van fysieke fitheid van HHS`,url:`https://www.cdc.gov/physical-activity-basics/about/index.html`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};